import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()

    category_map = {
        "Office Suplies": "Office Supplies",
        "Accesories": "Accessories"
    }
    if "Category" in df.columns:
        df["Category"] = df["Category"].map(lambda x: x.strip() if isinstance(x, str) else x)
        df["Category"] = df["Category"].replace(category_map)

    if "Region" in df.columns:
        df["Region"] = df["Region"].map(lambda x: x.strip() if isinstance(x, str) else x)
        df["Region"] = df["Region"].replace({" East": "East"})

    if {"Quantity", "Price"}.issubset(df.columns):
        df["Revenue"] = pd.to_numeric(df["Quantity"], errors="coerce") * pd.to_numeric(df["Price"], errors="coerce")

    return df

def answer(df):
    d = df.dropna(subset=["Category"])
    grouped = d.groupby("Category", dropna=True)["Revenue"].sum().sort_index()
    return {str(k): float(v) for k, v in grouped.items()}
